// Common culprit: Static collections acting as hidden memory leaks
public class CacheManager {
    // Static fields are GC roots; objects added here will never be garbage collected
    private static final Map<String, LargeObject> CACHE = new ConcurrentHashMap<>();

    public void addToCache(String key, LargeObject obj) {
        CACHE.put(key, obj); // If this map grows indefinitely, OOM is inevitable
    }
}
